package exercise
import("bytes";"encoding/json";"errors";"io";"strconv";"strings")
type Config struct{Name string;Retries int;TLSEnabled bool;ServerName string}
func value(d *json.Decoder,depth int)(any,error){
 if depth>32{return nil,errors.New("too deep")};token,err:=d.Token();if err!=nil{return nil,err};delim,ok:=token.(json.Delim);if !ok{return token,nil}
 switch delim{case '{':
  m:=map[string]any{};for d.More(){k,e:=d.Token();if e!=nil{return nil,e};key,ok:=k.(string);if !ok{return nil,errors.New("key")};if _,exists:=m[key];exists{return nil,errors.New("duplicate key")};v,e:=value(d,depth+1);if e!=nil{return nil,e};m[key]=v};end,e:=d.Token();if e!=nil||end!=json.Delim('}'){return nil,errors.New("object end")};return m,nil
 case '[':
  a:=[]any{};for d.More(){v,e:=value(d,depth+1);if e!=nil{return nil,e};a=append(a,v)};end,e:=d.Token();if e!=nil||end!=json.Delim(']'){return nil,errors.New("array end")};return a,nil
 };return nil,errors.New("unexpected delimiter")
}
func Parse(data []byte)(Config,error){
 bad:=func()(Config,error){return Config{},errors.New("invalid config")};if len(data)>4096{return bad()};d:=json.NewDecoder(bytes.NewReader(data));d.UseNumber();raw,e:=value(d,0);if e!=nil{return bad()};if _,e=d.Token();e!=io.EOF{return bad()}
 m,ok:=raw.(map[string]any);if !ok||len(m)!=3{return bad()};name,ok:=m["name"].(string);if !ok||strings.TrimSpace(name)==""{return bad()};number,ok:=m["retries"].(json.Number);if !ok{return bad()};n,e:=strconv.Atoi(string(number));if e!=nil||n<0||n>5{return bad()}
 tls,ok:=m["tls"].(map[string]any);if !ok||len(tls)!=2{return bad()};enabled,ok:=tls["enabled"].(bool);if !ok{return bad()};server,ok:=tls["server_name"].(string);if !ok||(enabled&&strings.TrimSpace(server)==""){return bad()};return Config{Name:name,Retries:n,TLSEnabled:enabled,ServerName:server},nil
}
