package exercise
import("strings";"testing")
func TestStrictSchemaAndJSONBoundaries(t *testing.T){
 good:=`{"name":"api","retries":3,"tls":{"enabled":true,"server_name":"api.example"}}`;got,e:=Parse([]byte(good));if e!=nil||got!=(Config{Name:"api",Retries:3,TLSEnabled:true,ServerName:"api.example"}){t.Fatal("valid config",got,e)}
 invalid:=[]string{
 `{"name":"a","name":"b","retries":0,"tls":{"enabled":false,"server_name":""}}`,
 `{"name":"a","na\u006de":"b","retries":0,"tls":{"enabled":false,"server_name":""}}`,
 `{"Name":"a","retries":0,"tls":{"enabled":false,"server_name":""}}`,
 `{"name":"a","retries":0,"tls":{"enabled":true,"enabled":false,"server_name":"x"}}`,
 `{"name":"a","retries":1.0,"tls":{"enabled":false,"server_name":""}}`,
 `{"name":"a","retries":6,"tls":{"enabled":false,"server_name":""}}`,
 `{"name":"a","retries":null,"tls":{"enabled":false,"server_name":""}}`,
 `{"name":"a","retries":0,"tls":{"enabled":true,"server_name":""}}`,
 `{"name":"a","retries":0,"tls":{"enabled":false,"server_name":"","extra":1}}`,
 `{"name":"a","retries":0,"tls":{"enabled":false,"server_name":""}} {}`,
 `{"name":"a","retries":0,"tls":{"enabled":false,"server_name":""}} trailing`,
 strings.Repeat("[",35)+strings.Repeat("]",35),strings.Repeat(" ",4097),`null`,
 }
 for _,input:=range invalid{c,e:=Parse([]byte(input));if e==nil||c!=(Config{}){t.Fatalf("ambiguous or malformed config accepted: %q %#v %v",input,c,e)}}
 t.Log("NATIVE_GO_JSON_DUPLICATE_ESCAPED_KEY_CASE_SCHEMA_NUMERIC_AND_TRAILING_REJECTED")
}
